needs "n12/geometry/CP_FiniteCases_C997Entrance.ml";;
needs "n12/geometry/Helpers.ml";;

(* Lean: budget_count (private) *)
let C997D_BUDGET_COUNT = prove
 (`forall k. k < 2 ==> CARD (c997e_family INTER auxex k) = 3`,
  REWRITE_TAC[ARITH_RULE `k < 2 <=> k = 0 \/ k = 1`] THEN GEN_TAC THEN
  DISCH_THEN (DISJ_CASES_THEN SUBST1_TAC) THEN
  REWRITE_TAC[card_exempt C997E_F 0; card_exempt C997E_F 1]);;

